【図解】三現象の前兆と即時措置
　現象｜現場で見える前兆｜即時措置｜
　ヒービング｜背面地盤の沈下・切梁軸力急増｜掘削中止・埋戻し・盛替え
　ボイリング｜底面から砂混じり水の湧出｜掘削中止・注水し水位差を減らす
