そこで壁を内側から突っ張ったり、外側の地中に引っ張ったりして支えます。
・水平切梁工法＝穴の中を横に材を渡して突っ張る、最も一般的
・地盤アンカー工法＝壁の背面の固い地盤に鋼線を定着して引っ張る
