・中間杭：切梁の座屈長さを短くし、自重を支える鉛直材
・地盤アンカー：引張材（PC鋼より線）＋定着体（グラウト）＋アンカー頭部
・支保工材はJIS適合の鋼材を用い、再使用材は変形・断面欠損を検査する

