━━━━━━━━━━━━━━━━━━━━━━
・搬入時：杭体のひび割れ、端板の変形、寸法・強度証明書の確認
・施工中：オーガー電流値の記録、根固め液の注入量と練り上がり試料の採取
・根固め部の強度：現場でサンプリングした供試体の圧縮強度試験
・施工後：杭心のずれと鉛直度の実測、杭頭レベルの確認
・必要に応じて杭の鉛直載荷試験や低ひずみ試験（健全性試験）

━━━━━━━━━━━━━━━━━━━━━━
