・打設・沈設後：杭心のずれ、鉛直度、杭頭レベルを実測
・杭頭処理：余盛り部をはつり取り、所定のレベルで平滑に仕上げる

【図解】杭の位置・精度の管理値
　項目｜管理値｜備考｜
