そういう地盤は、固める・締める・水を抜く、といった手を加えて
使える地盤に作り変えます。これが地盤改良です。
・固める＝セメント系固化材や薬液を混ぜて土を硬くする
・締める＝振動や砂杭で土の隙間を減らし、密にする
・水を抜く＝排水路をつくって圧密を早め、沈下を先に済ませる
