鉄筋は所定の位置にあってはじめて設計どおりの強さを発揮します。
コンクリートを流し込むときには大きな力がかかり、作業員も上を歩きます。
それでも動かないように、交点を細い針金で縛り、支えを入れて固定します。
・結束線＝鉄筋どうしを縛って位置を保持する（力を伝える部材ではない）
・スペーサー＝型枠との距離を保ち、かぶりを確保する
・バーサポート・幅止め筋＝上下・左右の間隔を保持する
組み上がった状態を第三者が確認するのが配筋検査で、
コンクリートを打ってしまうと二度と直せないため極めて重要です。

