・かぶり厚さ：スケールまたはかぶり厚さ測定器で複数点を測定
・継手：位置、重ね長さ、ずらし量、圧接部の外観
・定着：定着長さと投影長さ、定着起点の位置
・補強筋：開口補強、隅部補強、差し筋の有無と位置
・清掃と養生：型枠内の異物、鉄筋への油・泥の付着
・記録：黒板を入れて写真撮影し、部位ごとに整理して保管する
・是正確認：指摘事項は是正後に再検査し、是正前後の写真を残す
・型枠建込み後は、鉄筋とせき板のクリアランスを再度確認する

