何日もかけてゆっくり進み、水が足りなくなると途中で止まります。
表面が乾いてしまうと、そこだけ強度が出ず、ひび割れが入ります。
また、固まる前に凍ってしまうと、内部の水が膨張して組織が壊れます。
・湿潤養生＝水分を逃さない、あるいは補い続ける
・温度養生＝寒いときは温め、暑いときは冷やす
・保護養生＝振動や衝撃、荷重から守る
