・マスコンクリート：内部と表面の温度差を小さくするため、
　表面を保温して急冷を防ぐ（外部拘束と内部拘束の両方に配慮）
・コンクリート打込み後の表面の風速を抑え、乾燥収縮を防ぐ

━━━━━━━━━━━━━━━━━━━━━━
