　構造体強度推定用（現場封かん養生または現場水中養生）、
　脱型判定用（現場水中養生）を分けて採取する
・識別：打設部位、打設日、ミキサ車番号を明記する

【図解】養生方法と使いみち
　養生方法｜主な使いみち｜比べる相手｜
