━━━━━━━━━━━━━━━━━━━━━━
・溶接前：開先の形状・清浄度、裏当て金の密着、仮付けの状態
・溶接中：電流・電圧・速度、予熱温度、パス間温度の記録
・溶接後の外観検査：割れ、アンダーカット、オーバーラップ、
　ピット、余盛り高さ、ビード形状
・内部欠陥：超音波探傷試験による抜取りまたは全数検査
・溶接技能者の資格と、実施した溶接箇所の記録を照合する

