鉄骨の梁の上にコンクリートの床を載せただけでは、両者は別々に動きます。
そこで梁の上面に短い鋼の棒（頭付きスタッド）を立てて溶接し、
コンクリートに埋め込むことで、梁と床が一体となって働くようにします。
デッキプレートは、その床コンクリートを受ける波形の鋼板で、
型枠を兼ねたり、床の鉄筋の役割を兼ねたりします。
・スタッド溶接＝瞬間的に大電流を流して溶かし、押し付けて接合する
・デッキプレート＝型枠用と、鉄筋を兼ねる合成スラブ用がある

