・変成シリコーン系：金属パネル、ALC、コンクリートに広く用いる。
　上に塗装ができる★
・ポリサルファイド系：石張り、タイル張りの目地。
　表面に汚れが付きにくい★
・ポリウレタン系：コンクリート、ALCの目地。耐候性に劣るため
　露出部にはあまり用いない
・アクリルウレタン系：外装の一般目地に用いる
・バックアップ材、ボンドブレーカー、プライマー、マスキングテープ

