外壁に石を張るとき、昔はモルタルで塗り付けて固定していました。
これが湿式工法です。しかしモルタルは乾くのに時間がかかり、
白い汚れ（白華）が出たり、地震で剥がれ落ちたりします。
そこで金物で機械的に固定する乾式工法が主流になりました。
