・注入する樹脂の量：所定量を確実に注入し、あふれで確認
・張替えの場合、既存の張付けモルタルまで完全に撤去する
・改修後は、再度打診と引張接着試験で確認する

━━━━━━━━━━━━━━━━━━━━━━
