・既調合軽量モルタル：軽量骨材を用い、ひび割れが少ない
・吸水調整材：下地の過度の吸水を抑え、接着を確保する
・ラス、ワイヤラス、メタルラス：ひび割れ防止と付着の確保
・仕上げ材：しっくい、せっこうプラスター、ドロマイトプラスター

