床にビニル床シートやカーペット、フローリングを張るには、
下地が非常に平らである必要があります。こてで塗って平らにするには
熟練が要り、時間もかかります。そこで、水のようによく流れる材料を
流し込み、重力で自然に水平になるのを待つ方法が生まれました。
これがセルフレベリング材（SL材）です。
・流し込むだけなので、広い面積を短時間で平滑にできる
・ただし、風が当たると表面だけ先に乾いてしわが寄る
・下地の吸水があると、材料の水が吸われて硬化不良になる
